const inputItem = $input.first().json;
const body = inputItem.body || inputItem;

// Filter out WAHA non-message events (status pings, ack, etc.)
if (body.event && body.event !== 'message' && body.event !== 'message.any') {
  return [];
}

let senderPhone = '';
let receiverLine = '254768141129';
let senderName = 'Customer';
let messageText = '';
let messageId = 'msg_' + Date.now();
let referralSource = 'direct';
let provider = 'WAHA';
let rawChatId = '';

// 1. Meta Cloud API Payload
if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value) {
  provider = 'META_CLOUD_API';
  const val = body.entry[0].changes[0].value;
  if (val.statuses) return [];

  receiverLine = val.metadata?.display_phone_number?.replace(/[^0-9]/g, '') || '254768141129';
  if (val.contacts && val.contacts[0]) {
    senderName = val.contacts[0].profile?.name || senderName;
    senderPhone = val.contacts[0].wa_id || '';
  }
  if (val.messages && val.messages[0]) {
    const msg = val.messages[0];
    messageId = msg.id || messageId;
    senderPhone = senderPhone || msg.from || '';
    if (msg.type === 'text') messageText = msg.text?.body || '';
    else if (msg.type === 'button') messageText = msg.button?.text || '';
    else if (msg.type === 'interactive') messageText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
    if (msg.referral) referralSource = msg.referral.source_type || 'ad_campaign';
  }
  rawChatId = senderPhone ? senderPhone + '@c.us' : '';
} 
// 2. Telegram Inbound Payload (@fv_rzkbot)
else if (body.message && body.message.chat) {
  provider = 'TELEGRAM';
  const msg = body.message;
  rawChatId = String(msg.chat.id);
  senderPhone = String(msg.from?.id || msg.chat.id);
  receiverLine = '254768141129';
  senderName = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.from?.username || 'Telegram Client';
  messageText = msg.text || '';
  messageId = String(msg.message_id || Date.now());
  referralSource = 'telegram';
}
// 3. WAHA Inbound Payload
else if (body.payload && (body.event === 'message' || body.event === 'message.any')) {
  if (body.payload.fromMe) return [];
  provider = 'WAHA';
  rawChatId = body.payload.from || body.payload.chatId || '';
  senderPhone = (rawChatId || '').replace(/@.*$/, '').replace(/[^0-9]/g, '');
  receiverLine = (body.session || body.payload.to || '').replace(/[^0-9]/g, '') || '254768141129';
  senderName = body.payload._data?.notifyName || body.payload.notifyName || senderName;
  messageText = body.payload.body || '';
  messageId = body.payload.id || messageId;
} 
// 4. Direct Test Webhook / Browser Simulator
else {
  provider = body.channel_provider || 'DIRECT_TEST';
  senderPhone = String(body.phone || body.sender || '254768141129').replace(/[^0-9]/g, '');
  receiverLine = String(body.receiver || body.business_phone || '254768141129').replace(/[^0-9]/g, '');
  senderName = body.name || senderName;
  messageText = body.message || body.text || 'Hello';
  referralSource = body.source || 'direct';
  rawChatId = body.chatId || (senderPhone + '@c.us');
}

if (!messageText || !senderPhone) {
  return [];
}

return [{
  json: {
    sender_phone: senderPhone,
    chat_id: rawChatId,
    receiver_line: receiverLine,
    sender_name: senderName,
    message_text: messageText,
    message_id: messageId,
    referral_source: referralSource,
    channel_provider: provider,
    rag_context: body.ragContext || '',
    received_at: new Date().toISOString()
  }
}];

const normalized = $('Universal Normalizer & Dedupe').first().json;
const lineRecords = $input.first().json;

let line = Array.isArray(lineRecords) && lineRecords.length > 0 ? lineRecords[0] : (lineRecords && lineRecords.id ? lineRecords : null);
let tenant = line?.tenants || {};
let agentConfig = tenant.tenant_agent_configs || {};
let catalog = tenant.catalog_items || [];

const businessName = tenant.business_name || 'P3L Developers';
const ownerEmail = tenant.owner_email || 'razakwako45@gmail.com';
const agentName = agentConfig.agent_name || 'Odin-P3L';
const currency = tenant.currency || 'KES';
const opHours = tenant.operating_hours ? `Mon-Fri: ${tenant.operating_hours.mon_fri || '08:00-18:00'}, Sat-Sun: ${tenant.operating_hours.sat_sun || '09:00-14:00'}` : 'Monday to Friday 8:00 AM to 6:00 PM, Saturday and Sunday 9:00 AM to 2:00 PM';
const deliveryInfo = tenant.delivery_zones ? `${tenant.delivery_zones.coverage}: ${tenant.delivery_zones.details}` : 'Nairobi same-day express dispatch via Super Metro Parcels, Pickup Mtaani lockers, or direct motorbike rider. Countrywide upcountry next-day delivery via Wells Fargo Courier or G4S.';

// Catalog with explicit image URLs for media sharing
let catalogText = catalog.map((item, idx) => {
  let entry = `${idx + 1}. [${(item.item_type || 'item').toUpperCase()}] ${item.category}: **${item.name}** - **${currency} ${Number(item.base_price_kes).toLocaleString()}** (${item.in_stock ? 'In Stock' : 'Out of Stock'}) | ${item.description || ''}`;
  if (item.image_url) {
    entry += ` | Media Photo Link: ${item.image_url}`;
  }
  return entry;
}).join('\n');

const systemInstructions = `You are ${agentName}, the professional consultative sales and technical solutions advisor for ${businessName} in Nairobi, Kenya.

ABOUT THE ENTERPRISE:
- Organization: ${businessName}
- Focus: Premier enterprise technology engineering firm, bespoke AI and automation solutions, and authorized provider of high-performance computing hardware, laptops, Apple workstations, monitors, and precision repair services across Kenya.
- Operations Email: ${ownerEmail}
- Operating Hours: ${opHours}
- Delivery Network: Same-day dispatch across Nairobi and surroundings via Super Metro Parcels, Pickup Mtaani, or motorbike rider. Next-day guaranteed delivery countrywide via Wells Fargo Courier or G4S.
- Currency: ${currency}

CRITICAL RULES ON IDENTITY & BRANDING:
1. You represent an established, high-caliber technology firm. NEVER recite personal founder bios, personal college or university details, age, or personal background when asked about the company or what we do.
2. If asked about the business, present ${businessName} as a premier technology engineering firm and hardware supplier with enterprise software capabilities, top-tier computing inventory, full 1-year warranties, and professional repairs.

CRITICAL RULES ON TONE & FORMATTING:
1. Talk naturally, warmly, and concisely like an expert, attentive human tech consultant or sales executive.
2. NEVER use emojis under any circumstances (no rockets, laptops, checkmarks, phones, fire, stars).
3. NEVER use star bullet lists (* item). Write in clean, smooth, readable sentences and paragraphs.
4. When you need to highlight something important (such as product names, exact prices in KES, account numbers, warranties, or contact info), ALWAYS use bold formatting (**like this**).

MEDIA & IMAGE SHARING:
1. You have direct access to image URLs and media links for our products in the catalog.
2. If the customer asks to see pictures, photos, samples, or links for any item, share the direct media photo link from the catalog so they can view it.

PAYMENT INSTRUCTIONS & HONESTY:
1. Official Payment Methods:
   - M-Pesa Pochi La Biashara: Send payment directly to phone number **0768141129** (Instant, zero transaction fee).
   - M-Pesa Paybill: Business Number **255255**, Account Number: **Customer Name & Item Ordered**.
   - Cash on Delivery: Available within Nairobi CBD upon minimal rider dispatch commitment.
2. STRICT TRUTH LAW: NEVER claim or imply that an automatic STK PIN prompt has been sent to their phone screen. Always instruct the customer to send payment manually to Pochi La Biashara (**0768141129**) or Paybill **255255**, and reply here with the Safaricom confirmation message to dispatch immediately.
3. If the customer confirms an order or wants to pay, call initiate_mpesa_payment.

HUMAN ESCALATION & SUPPORT:
1. If the customer encounters an issue, says payment did not go through, requests custom enterprise contracts, or explicitly asks for a human specialist, immediately call escalate_to_human_agents.
2. State clearly that our senior technical operations team at **${ownerEmail}** has been alerted with their chat details and will assist promptly.

STRICT CATALOG LAW:
Never invent products, specs, or discounts that do not exist in the catalog. Quote exact prices from the verified list below.

OFFICIAL VERIFIED CATALOG:
${catalogText || 'All catalog items loaded dynamically.'}`;

return [{
  json: {
    ...normalized,
    tenant_id: tenant.id || '11111111-1111-1111-1111-111111111111',
    business_name: businessName,
    owner_email: ownerEmail,
    currency: currency,
    provider: normalized.channel_provider || line?.provider || 'WAHA',
    meta_phone_number_id: line?.meta_phone_number_id || null,
    meta_access_token: line?.meta_access_token || null,
    waha_endpoint_url: line?.waha_endpoint_url || 'http://localhost:5000',
    system_instructions: systemInstructions,
    message_text: normalized.message_text
  }
}];

const context = $('Assemble Agent Context & Guard').first().json;
return JSON.stringify({
  action: 'manual_mpesa_payment_instructions',
  pochi_la_biashara: '0768141129',
  paybill_number: '255255',
  account_format: '<Customer Name> & <Item Ordered>',
  business: context.business_name,
  currency: context.currency,
  instructions: 'Instruct the customer to send payment via M-Pesa Pochi La Biashara to 0768141129 or Paybill 255255 with account <Name & Item>. Do not promise an STK push popup on their screen. Once paid, they should paste the Safaricom confirmation message here for immediate dispatch.'
});

const context = $('Assemble Agent Context & Guard').first().json;
return JSON.stringify({
  escalation_triggered: true,
  escalation_email: context.owner_email || 'razakwako45@gmail.com',
  business: context.business_name,
  message: 'Human escalation alert dispatched to operations team at ' + (context.owner_email || 'razakwako45@gmail.com') + ' and senior manager alerted.'
});

const agentOutput = $input.first().json.output || 'Hello! Thank you for contacting P3L Developers. A specialist will assist you shortly.';
const originalContext = $('Assemble Agent Context & Guard').first().json;

const isEscalation = /escalat|human|agent|operations team|razakwako45@gmail\.com|human support|operator/i.test(agentOutput) ||
                     /human|agent|operator|manager|call me|payment fail|didn't go through|not going through/i.test(originalContext.message_text || '');

return [{
  json: {
    success: true,
    status: 'delivered',
    chatId: originalContext.chat_id || (originalContext.sender_phone + '@c.us'),
    phone: originalContext.sender_phone,
    customer_name: originalContext.sender_name || 'Valued Client',
    message_text: originalContext.message_text,
    text: agentOutput,
    reply: agentOutput,
    provider: originalContext.provider,
    is_escalation: isEscalation,
    escalation_email: originalContext.owner_email || 'razakwako45@gmail.com',
    business_name: originalContext.business_name || 'P3L Developers',
    meta_phone_number_id: originalContext.meta_phone_number_id,
    meta_access_token: originalContext.meta_access_token,
    waha_endpoint_url: originalContext.waha_endpoint_url,
    timestamp: new Date().toISOString()
  }
}];
